package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.EnchantmentHelper;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.Aspect;
import thaumcraft.common.tiles.infusion.InfusionEnchantments;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class InfusionEnchantAudit {
 static int ticks,spreads;static volatile boolean prepared,repairDone,hasteDone;static int xp;static final BlockPos POS=InfusionAudit.POS;static InfusionContent.MatrixEntity matrix;static String current;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_INFENCH FAIL "+s);System.out.println("TC4_INFENCH PASS "+s);}
 static ItemStack item(String id){return new ItemStack(BuiltInRegistries.ITEM.get(AlchemyContent.id(id)));}
 static void start(ServerPlayer p,String key,ItemStack central){current=key;var l=p.serverLevel();var recipe=InfusionEnchantments.all(()->InfusionContent.SALIS.get()).stream().filter(r->r.key().equals(key)).findFirst().orElseThrow();var holder=InfusionEnchantments.holder(l.registryAccess(),recipe.enchantment());
  check(recipe.acceptsCentral(central,holder),"correct central target "+key);var bad=central.copy();bad.enchant(holder,holder.value().getMaxLevel());check(!recipe.acceptsCentral(bad,holder),"max level rejected "+key);check(!recipe.acceptsCentral(new ItemStack(Items.DIRT),holder),"invalid central target rejected "+key);
  ((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).setItem(central);for(int i=0;i<InfusionAudit.components.size();i++)((InfusionContent.PedestalEntity)l.getBlockEntity(InfusionAudit.components.get(i))).setItem(i<recipe.components().size()?new ItemStack(recipe.components().get(i).get()):ItemStack.EMPTY);
  int i=0;for(var a:recipe.aspects().getAspects()){var pos=POS.offset(i++*2-2,-2,-4);l.setBlock(pos,EssentiaDevices.JAR.get().defaultBlockState(),3);var jar=(WardedJarEntity)l.getBlockEntity(pos);jar.state.aspect=a;jar.state.amount=recipe.aspects().getAmount(a);jar.changed();}
  InfusionAudit.click(p,p.getInventory().items.stream().filter(WandData::isWand).findFirst().orElseThrow());check(matrix.logic.crafting&&matrix.logic.recipeType==1&&matrix.logic.recipeEnchantment.equals(holder)&&matrix.logic.recipeXP==recipe.baseXP(holder),"actual wand starts enchantment with correct XP "+key);
  var saved=matrix.saveWithFullMetadata(l.registryAccess());var copy=new InfusionContent.MatrixEntity(POS,matrix.getBlockState());copy.loadWithComponents(saved,l.registryAccess());check(copy.logic.recipeEnchantment.equals(holder)&&copy.logic.recipeXP==matrix.logic.recipeXP&&copy.logic.recipeType==1,"enchantment and XP persist "+key);
 }
 static void finish(ServerPlayer p,String key){var l=p.serverLevel();var recipe=InfusionEnchantments.all(()->InfusionContent.SALIS.get()).stream().filter(r->r.key().equals(key)).findFirst().orElseThrow();var holder=InfusionEnchantments.holder(l.registryAccess(),recipe.enchantment());var center=((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).item();check(!matrix.logic.crafting&&EnchantmentHelper.getItemEnchantmentLevel(holder,center)==1,"natural altar finishes level1 "+key);check(p.experienceLevel==xp-recipe.baseXP(holder),"exact original XP levels consumed "+key);xp=p.experienceLevel;for(var pos:InfusionAudit.components)check(((InfusionContent.PedestalEntity)l.getBlockEntity(pos)).item().isEmpty(),"components consumed "+key+pos);int i=0;for(var a:recipe.aspects().getAspects())check(((WardedJarEntity)l.getBlockEntity(POS.offset(i++*2-2,-2,-4))).state.amount==0,"exact essentia consumed "+a.getTag());}
 static void prepare(ServerPlayer p){InfusionAudit.prepare(p);matrix=InfusionAudit.matrix;matrix.logic.crafting=false;p.giveExperienceLevels(20-p.experienceLevel);xp=20;
  var all=InfusionEnchantments.all(()->InfusionContent.SALIS.get());check(all.size()==24,"all24 original infusion enchantments registered");for(var r:all){var holder=InfusionEnchantments.holder(p.level().registryAccess(),r.enchantment());check(holder.value().getMaxLevel()>0&&r.components().size()>=2,"valid enchantment holder and original components "+r.key());}
  start(p,"InfEnchRepair",item("thaumium_pickaxe"));prepared=true;
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.enchantAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==130){check(prepared,"server setup complete");LiquidDeathAudit.shot(mc,"infusion-enchant-repair.png");}if(ticks==850)server.execute(()->{var p=server.getPlayerList().getPlayer(id);finish(p,"InfEnchRepair");repairDone=true;start(p,"InfEnchHaste",new ItemStack(TC4Modern.ROBE_BOOTS.get()));});if(ticks==870){check(repairDone,"repair infusion complete");LiquidDeathAudit.shot(mc,"infusion-enchant-haste.png");}if(ticks==1500)server.execute(()->{finish(server.getPlayerList().getPlayer(id),"InfEnchHaste");hasteDone=true;});if(ticks==1510){check(hasteDone,"haste infusion complete");LiquidDeathAudit.shot(mc,"infusion-enchant-finished.png");var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("INFUSIONENCHANTMENT"),0);mc.setScreen(book);spreads=(book.auditPageCount()+1)/2;check(spreads>=13,"all24enchants present in research pages");}if(ticks>=1520&&(ticks-1520)%10==0){int page=(ticks-1520)/10;if(page>=spreads){mc.stop();return;}((ThaumonomiconScreen)mc.screen).auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("INFUSIONENCHANTMENT"),page*2);}if(ticks>=1525&&(ticks-1525)%10==0)LiquidDeathAudit.shot(mc,"infusion-enchant-book-"+(ticks-1525)/10+".png");}
}
